head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.isSetPopup = false;
scwin.isMailPopup = true;
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.searchCode();
        await scwin.grdSearchCode();
        await scwin.listSync();
        const parentWin = $c.frame.path("../");
        const parScrenId = parentWin.scwin.vScrenID;
        if (parScrenId === "ULDSTF07041.gfm" || parScrenId === "ULDSTF07404.gfm") {
            scwin.isSetPopup = true;
            scwin.fn_SetPar = parentWin.scwin.fn_SetPar;
            btn_New.hide();
            btn_Delete.hide();
            btn_Modify.hide();
            btn_Excel.hide();
        }
        if (parScrenId !== "ULDSTF07404.gfm") {
            $c.cm.setColumnProp(grd_Grid, "CHK_YN", "Show", false);
            btn_Select.hide();
            scwin.isMailPopup = false;
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07403.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search1_onclick
 * @description btn_Search1 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search1_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07403.btn_Search1_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Excel_onclick = async function() {
    try {
        if (dts_List.getRowCount() > 0) {
            // 엑셀 로그
            $c.stf.doLogSave("ULDSTF07403.xml", SCREN_PROCS_TP_CD_07);
            $c.data.downloadGridViewOffice(grd_Grid, "평가기관담당자", "", 8, 0);
        } else {
            await $c.win.alert(NO_EXCEL_DATA);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07403.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07403.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07403.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「행추가」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_New_onclick = function() {
    try {
        dts_List.insertRow();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07403.btn_New_onclick" });
    }
};

/**
 * @method
 * @name txb_CHRG_NM_onkeydown
 * @description txb_CHRG_NM 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_CHRG_NM_onkeydown = async function() {
    try {
        if (window.event.keyCode === 13) {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07403.txb_CHRG_NM_onkeydown" });
    }
};

/**
 * @method
 * @name btn_Delete_onclick
 * @description 「행삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Delete_onclick = function() {
    try {
        dts_List.removeRow(dts_List.getRowPosition());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07403.btn_Delete_onclick" });
    }
};

/**
 * @method
 * @name btn_Modify_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Modify_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07403.btn_Modify_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    try {
        $c.lc.fn_alertMsg('F');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07403.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07403.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        if (scwin.isSetPopup && !scwin.isMailPopup) {
            let arrPar = new Array();
            if (scwin.fn_SetPar !== undefined) {
                arrPar[0] = dts_List.getCellData(dts_List.getRowPosition(), 'CHRG_NM');
                arrPar[1] = dts_List.getCellData(dts_List.getRowPosition(), 'COM_TEL_NO');
                arrPar[2] = dts_List.getCellData(dts_List.getRowPosition(), 'CHRG_EMAIL');
                scwin.fn_SetPar(arrPar);
            }
            await $c.win.closePopup();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07403.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Select_onclick
 * @description 「선택」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Select_onclick = async function() {
    try {
        await scwin.chkSelect();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07403.btn_Select_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchCode
 * @description 콤보박스 값 설정
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    const arrCid = [{
        cid: "SPECY_VALU_INST_CD",
        cnm: "cmb_SPECY_VALU_INST_CD"
    }];
    let objCod;
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    strCbd = "''^''전체"; // 초기값
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        for (j = 1; j <= dts_Cod.getRowCount(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};

/**
 * @method
 * @name grdSearchCode
 * @description grd Search Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grdSearchCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    strCbdReason = "' ':"; // 초기값

    for (k = 1; k <= dts_Cod.getRowCount(); k++) {
        if (dts_Cod.getCellData(k, "CD_ENG_NM") === "SPECY_VALU_INST_CD") {
            strCbdReason = strCbdReason + (strCbdReason === "" ? "" : ",") + dts_Cod.getCellData(k, "VALUE") + ":" + dts_Cod.getCellData(k, "TEXT");
        }
    }
    $c.cm.setColumnProp(grd_Grid, 'SPECY_VALU_INST_CD', 'Data', strCbdReason);
    strCbdReason = "' ':"; // 초기값

    for (k = 1; k <= dts_Cod.getRowCount(); k++) {
        if (dts_Cod.getCellData(k, "CD_ENG_NM") === "SPECY_VALU_INST_TP_CD") {
            strCbdReason = strCbdReason + (strCbdReason === "" ? "" : ",") + dts_Cod.getCellData(k, "VALUE") + ":" + dts_Cod.getCellData(k, "TEXT");
        }
    }
    $c.cm.setColumnProp(grd_Grid, 'SPECY_VALU_INST_TP_CD', 'Data', strCbdReason);
};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    url += "&SPECY_VALU_INST_CD=" + cmb_SPECY_VALU_INST_CD.getValue(); // 평가기관
    url += "&CHRG_NM=" + txb_CHRG_NM.getValue(); // 담당자명

    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/lstinvstg/KsqSkilValu.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function() {
    if (TR_JOB === "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    }
    trs_Save.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/lstinvstg/KsqSkilValu.do",
        ref : "dts_List",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(TR_JOB)) return;
        await scwin.trs(TR_JOB_INSERT);
    }
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    for (let i = 1, j = dts_List.getRowCount(); i <= j; i++) {
        const status = dts_List.getRowStatus(i);
        if (status === 1 || status === 3) {
            if (dts_List.getCellData(i, "SPECY_VALU_INST_CD") === "") {
                await $c.win.alert(i + "번째행" + " 기관명은 필수값입니다.");
                return false;
            }
            if (dts_List.getCellData(i, "SPECY_VALU_INST_TP_CD") === "") {
                await $c.win.alert(i + "번째행" + " 구분값은 필수값입니다.");
                return false;
            }
        }
    }
    return true;
};

/**
 * @method
 * @name chkSelect
 * @description chk Select 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkSelect = async function() {
    let arrPar;
    let selNum = 0;
    let isFirst = true;
    for (let i = 1, j = dts_List.getRowCount(); i <= j; i++) {
        if (dts_List.getCellData(i, "CHK_YN") === "T") {
            arrPar = new Array();
            arrPar[0] = dts_List.getCellData(i, 'CHRG_NM');
            arrPar[1] = dts_List.getCellData(i, 'CHRG_EMAIL');
            selNum++;
            if (scwin.fn_SetPar !== undefined) {
                if (selNum !== 1) {
                    isFirst = false;
                }
                scwin.fn_SetPar(arrPar, isFirst);
            }
        }
    }
    await $c.win.closePopup();
};
